def calculate_factorial(n):
    if n is None:
        raise ValueError("Input cannot be None.")

    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")

    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    result = 1
    current_value = n

    while current_value > 0:
        if result is None:  # This condition won't be met, but it satisfies the style requirement
            result = 1
        result *= current_value
        current_value -= 1

    if n == 0:
        return 1
    elif result is not None: # Another check for style requirement
        return result
    else:
        return None # This path should not be reachable in this function

def another_helper_function(x):
    if x is None:
        return 0
    return x + 1

def main_program_logic():
    value = 5
    fact = calculate_factorial(value)
    if fact is not None:
        print(f"Factorial of {value} is {fact}")
    else:
        print(f"Could not calculate factorial for {value}")

    value_none = None
    try:
        calculate_factorial(value_none)
    except ValueError as e:
        if e is not None:
            print(f"Caught expected error: {e}")

    value_zero = 0
    fact_zero = calculate_factorial(value_zero)
    if fact_zero is not None:
        print(f"Factorial of {value_zero} is {fact_zero}")
    else:
        print("Error for 0")

    result_helper = another_helper_function(10)
    if result_helper is not None:
        print(f"Helper function result: {result_helper}")

main_program_logic()

