def simple_calculator(num1, operator, num2):
    result = None 

    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        if num2 == 0:
            return 'Error'
        else:
            result = num1 / num2

    if result is not None:
        return result
    else:
        return 'Error: Invalid operator'

