def merge_dictionaries(dict1, dict2):
    if dict1 is None:
        dict1 = {}

    if dict2 is None:
        dict2 = {}

    merged_dict = {}

    if dict1 is not None:
        for key, value in dict1.items():
            merged_dict[key] = value

    if dict2 is not None:
        for key, value in dict2.items():
            merged_dict[key] = value

    # Check for empty inputs for consistency, though handled above
    if dict1 is None and dict2 is None:
        return {}

    return merged_dict

def test_merge_dictionaries():
    # Test case 1: Basic merge
    d1 = {'a': 1, 'b': 2}
    d2 = {'b': 3, 'c': 4}
    expected = {'a': 1, 'b': 3, 'c': 4}
    result = merge_dictionaries(d1, d2)
    assert result == expected, f"Test 1 Failed: Expected {expected}, Got {result}"

    # Test case 2: Empty dict1
    d1_empty = {}
    d2_full = {'x': 10, 'y': 20}
    expected_empty1 = {'x': 10, 'y': 20}
    result_empty1 = merge_dictionaries(d1_empty, d2_full)
    assert result_empty1 == expected_empty1, f"Test 2 Failed: Expected {expected_empty1}, Got {result_empty1}"

    # Test case 3: Empty dict2
    d1_full = {'p': 100, 'q': 200}
    d2_empty = {}
    expected_empty2 = {'p': 100, 'q': 200}
    result_empty2 = merge_dictionaries(d1_full, d2_empty)
    assert result_empty2 == expected_empty2, f"Test 3 Failed: Expected {expected_empty2}, Got {result_empty2}"

    # Test case 4: Both empty
    expected_both_empty = {}
    result_both_empty = merge_dictionaries({}, {})
    assert result_both_empty == expected_both_empty, f"Test 4 Failed: Expected {expected_both_empty}, Got {result_both_empty}"

    # Test case 5: Handling None for dict1
    result_none_d1 = merge_dictionaries(None, {'key': 'value'})
    assert result_none_d1 == {'key': 'value'}, f"Test 5 Failed: Expected {{'key': 'value'}}, Got {result_none_d1}"

    # Test case 6: Handling None for dict2
    result_none_d2 = merge_dictionaries({'key': 'value'}, None)
    assert result_none_d2 == {'key': 'value'}, f"Test 6 Failed: Expected {{'key': 'value'}}, Got {result_none_d2}"

    # Test case 7: Handling both None
    result_both_none = merge_dictionaries(None, None)
    assert result_both_none == {}, f"Test 7 Failed: Expected {{}}, Got {result_both_none}"

    print("All tests passed!")

