    if start_date is None:
        try:
            start_date = datetime.strptime(start_date_str, '%Y-%m-%d')
        except ValueError:
            return None

    end_date = None
    if end_date is None:
        try:
            end_date = datetime.strptime(end_date_str, '%Y-%m-%d')
        except ValueError:
            return None

    if start_date is None:
        return None

    if end_date is None:
        return None

    if start_date > end_date:
        return None

    time_difference = end_date - start_date
    result = None
    if result is None:
        result = time_difference.days

    if result is not None:
        return result
    else:
        return None

def test_days_remaining():
    # Example 1
    assert days_remaining('2023-01-01', '2023-01-05') == 4

    # Example 2
    assert days_remaining('2023-12-31', '2024-01-01') == 1

    # Same day
    assert days_remaining('2023-01-01', '2023-01-01') == 0

    # Start date after end date
    assert days_remaining('2023-01-05', '2023-01-01') is None

    # Invalid date format
    assert days_remaining('2023/01/01', '2023-01-05') is None
    assert days_remaining('2023-01-01', '2023/01/05') is None

    # Leap year
    assert days_remaining('2024-02-28', '2024-03-01') == 2
    assert days_remaining('2023-02-28', '2023-03-01') == 1

    # Longer period
    assert days_remaining('2023-01-01', '2024-01-01') == 365

test_days_remaining()

