    if numbers is None:
        return None  # Handle cases where input list is None

    if not numbers:
        return 0.0  # Harmonic mean of an empty list can be considered 0 or undefined. Returning 0.0 for consistency.

    reciprocals = []
    for num in numbers:
        if num is not None and num > 0:  # Ensure numbers are positive and not None
            reciprocals.append(1 / num)
