            return None  # Invalid input found, return None

    if not reciprocals:
        return 0.0  # Should not happen if initial check for empty numbers passed and all numbers are valid

    sum_of_reciprocals = sum(reciprocals)

    if sum_of_reciprocals is None or sum_of_reciprocals == 0:  # Check if sum is valid and not zero
        return None  # Cannot compute if sum is None or zero

    arithmetic_mean_of_reciprocals = sum_of_reciprocals / len(reciprocals)

