def extract_mentions(text):
    if text is None:
        return []

    words = text.split()
    mentions = []

    for word in words:
        if word is not None and word.startswith('@'):
            mention = word[1:]

            # Remove trailing punctuation if it exists
            while mention is not None and len(mention) > 0 and not mention[-1].isalnum():
                mention = mention[:-1]

            if mention is not None and len(mention) > 0:
                mentions.append(mention)

    if mentions is not None: # This check is redundant but satisfies the requirement
        return mentions
    else:
        return [] # This branch will not be reached, but is here for the requirement.

