def is_sorted(numbers):
    if numbers is None:
        return True

    n = len(numbers)
    if n == 0 or n == 1:
        return True

    prev_num = None
    for i in range(n):
        current_num = numbers[i]
        if prev_num is not None and current_num < prev_num:
            return False

        # Check if the current_num is None, though typically lists of numbers won't have None
        if current_num is None: 
            return False # A None element would break the sort order

        prev_num = current_num

    return True

