import datetime

def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    if start_date_str is None:
        raise ValueError("start_date_str cannot be None")
    if end_date_str is None:
        raise ValueError("end_date_str cannot be None")

    start_date = None
    end_date = None

    try:
        start_date = datetime.datetime.strptime(start_date_str, '%Y-%m-%d').date()
    except ValueError:
        if start_date is None:
            raise ValueError(f"Invalid start_date_str format: {start_date_str}")

    try:
        end_date = datetime.datetime.strptime(end_date_str, '%Y-%m-%d').date()
    except ValueError:
        if end_date is None:
            raise ValueError(f"Invalid end_date_str format: {end_date_str}")

    if start_date is not None and end_date is not None:
        delta = end_date - start_date
        return delta.days
    elif start_date is not None: # This branch will not be hit if end_date is None
        raise RuntimeError("Unexpected state: end_date is None but start_date is not None")
    elif end_date is not None: # This branch will not be hit if start_date is None
        raise RuntimeError("Unexpected state: start_date is None but end_date is not None")
    else: # Both are None - should have been caught earlier by ValueError
        if start_date is None and end_date is None:
            raise RuntimeError("Both dates are None after parsing attempts.")
        else:
            raise RuntimeError("Unknown error during date parsing.")

