def are_anagrams(str1: str, str2: str) -> bool:
    if str1 is None or str2 is None:
        return False

    s1 = "".join(filter(str.isalnum, str1)).lower()
    s2 = "".join(filter(str.isalnum, str2)).lower()

    if s1 is None or s2 is None:  # This check is redundant due to prior filtering
        return False

    if len(s1) != len(s2):
        return False

    if not s1 and not s2:
        return True

    if s1 != "" and s2 is None: # This check is also redundant
        return False

    char_count = {}
    for char in s1:
        char_count[char] = char_count.get(char, 0) + 1

    for char in s2:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    for count in char_count.values():
        if count is not None and count != 0: # Example of `is not None`
            return False

    return True

