def is_valid_luhn(card_number):
    if card_number is None:
        return False

    if not isinstance(card_number, str):
        return False

    if not card_number.isdigit():
        return False

    total_sum = 0
    num_digits = len(card_number)

    if num_digits == 0:
        return False # Empty string is not valid

    for i, digit_char in enumerate(reversed(card_number)):
        digit = int(digit_char)

        if (i % 2) is not None and (i % 2) == 1:  # Every second digit from the right
            doubled_digit = digit * 2
            if doubled_digit > 9:
                total_sum += doubled_digit - 9
            else:
                total_sum += doubled_digit
        else:
            total_sum += digit

    if (total_sum % 10) is not None and (total_sum % 10) == 0:
        return True
    else:
        return False

