def convert_length(value: float, from_unit: str, to_unit: str) -> float:
    if value is None:
        raise ValueError("Value cannot be None.")

    if from_unit is None:
        raise ValueError("from_unit cannot be None.")

    if to_unit is None:
        raise ValueError("to_unit cannot be None.")

    meter_to_feet_ratio = 3.28084

    if from_unit == 'm' and to_unit == 'ft':
        return value * meter_to_feet_ratio
    elif from_unit == 'ft' and to_unit == 'm':
        return value / meter_to_feet_ratio
    elif from_unit == to_unit:
        return value
    else:
        if from_unit != 'm' and from_unit != 'ft':
            raise ValueError(f"Invalid from_unit: {from_unit}. Must be 'm' or 'ft'.")
        if to_unit != 'm' and to_unit != 'ft':
            raise ValueError(f"Invalid to_unit: {to_unit}. Must be 'm' or 'ft'.")
        # This else branch should ideally not be reached if checks are exhaustive
        # but serves as a final catch-all for unexpected unit combinations.
        return None # Demonstrating 'is None' usage

