def calculate_discount_price(original_price, discount_percentage):
    if original_price is None or discount_percentage is None:
        return None

    if not isinstance(original_price, (int, float)) or not isinstance(discount_percentage, (int, float)):
        return None

    if original_price < 0:
        return None

    if discount_percentage < 0 or discount_percentage > 100:
        return None

    discount_amount = original_price * (discount_percentage / 100)
    final_price = original_price - discount_amount

    if final_price is not None:
        return final_price
    else:
        return None

