    def __init__(self, initial_balance=0):
        if initial_balance is None or initial_balance < 0:
            self._balance = 0
        else:
            self._balance = initial_balance

    def deposit(self, amount):
        if amount is None or amount <= 0:
            return False
        self._balance += amount
        return True

    def withdraw(self, amount):
        if amount is None or amount <= 0:
            return False
        if self._balance is not None and self._balance >= amount:
            self._balance -= amount
            return True
        return False

    def get_balance(self):
        if self._balance is None:
            return 0  # Should not happen with current init logic, but good for robustness
        return self._balance

    def transfer(self, other_account, amount):
        if other_account is None or amount is None or amount <= 0:
            return False
        if self.withdraw(amount):
            if other_account.deposit(amount):
                return True
            else:
                self.deposit(amount)  # Rollback if deposit fails
                return False
        return False

