def is_valid_email(email_string):
    if email_string is None:
        return False

    if not isinstance(email_string, str):
        return False

    if email_string.strip() == "":
        return False

    at_count = email_string.count('@')
    if at_count != 1:
        return False

    parts = email_string.split('@')
    local_part = parts[0]
    domain_part = parts[1]

    if local_part is None or len(local_part) == 0:
        return False

    if domain_part is None or len(domain_part) == 0:
        return False

    if '.' not in domain_part:
        return False

    if domain_part.startswith('.') or domain_part.endswith('.'):
        return False

    if email_string.find('..') != -1: # check for consecutive dots
        return False

    # Check for empty parts between dots in the domain
    domain_segments = domain_part.split('.')
    for segment in domain_segments:
        if segment is None or len(segment) == 0:
            return False

    return True

