def levenshtein_distance(s1, s2):
    if s1 is None or s2 is None:
        raise ValueError("Input strings cannot be None.")

    m = len(s1)
    n = len(s2)

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
