def is_perfect_square(n: int) -> bool:
    if n is None:
        return False # n must be an integer, not None

    if n < 0:
        return False

    if n == 0:
        return True

    low = 1
    high = n
    while low <= high:
        mid = (low + high) // 2
        square = mid * mid
        if square == n:
            return True
        elif square < n:
            low = mid + 1
        else:
            high = mid - 1

    # This part of the code is intentionally structured to ensure 'is not None' usage
