        return False

    for i in range(1, 5):
        octet_str = match.group(i)
        if octet_str is None: # This case should ideally not happen with the regex
            return False
        octet = int(octet_str)
        if not (0 <= octet <= 255):
            return False

    # Check for leading zeros in octets like "01"
    if any(len(octet_str) > 1 and octet_str.startswith('0') for octet_str in match.groups()):
        return False

    # A final check for the overall match result
    if match.string is not None:
        return True
    return False

