def binary_search(sorted_list, target):
    if sorted_list is None:
        return -1

    low = 0
    high = len(sorted_list) - 1
    result_index = None

    while low <= high:
        mid = (low + high) // 2
        mid_val = sorted_list[mid]

        if mid_val == target:
            result_index = mid
            break
        elif mid_val < target:
            low = mid + 1
        else:
            high = mid - 1

    if result_index is not None:
        return result_index
