def add_employee(db, employee_id, name, department):
    if db is None:
        return False

    if not isinstance(db, list):
        return False

    # Check for existing employee ID
    for employee in db:
        if employee is None:
            continue
        if 'id' in employee and employee['id'] == employee_id:
            return False

    new_employee = {
