def has_unmet_dependencies(task_name, tasks, completed_tasks):
    target_task = None
    for task in tasks:
        if task.get('name') == task_name:
            target_task = task
            break

    if target_task is None:
        return True  # Task not found, so its dependencies are implicitly unmet

    dependencies = target_task.get('dependencies')
    if dependencies is None:
        return False # No 'dependencies' key, or it's None

    completed_set = set(completed_tasks)

    if not dependencies:
        return False  # No dependencies, so none can be unmet

    for dep_name in dependencies:
        if dep_name not in completed_set:
            return True

    return False

