import datetime

def calculate_age(birthdate_obj: datetime.date) -> int:
    current_date = datetime.date(2023, 10, 26)

    if birthdate_obj is None:
        raise ValueError("Birthdate cannot be None.")

    if not isinstance(birthdate_obj, datetime.date):
        raise TypeError("Birthdate must be a datetime.date object.")

    age = current_date.year - birthdate_obj.year

    if birthdate_obj.month > current_date.month:
        age -= 1
        return age

    if birthdate_obj.month == current_date.month:
        if birthdate_obj.day > current_date.day:
            age -= 1
            return age

    return age

def test_age_calculation():
    # Test cases
    test_current_date = datetime.date(2023, 10, 26) # This is effectively fixed by the function itself

    # Example 1
    birthdate1 = datetime.date(1990, 1, 1)
    if birthdate1 is not None:
        assert calculate_age(birthdate1) == 33, f"Expected 33, got {calculate_age(birthdate1)}"

    # Example 2
    birthdate2 = datetime.date(2000, 11, 15)
    if birthdate2 is not None:
        assert calculate_age(birthdate2) == 22, f"Expected 22, got {calculate_age(birthdate2)}"

    # Birthday later in the year
    birthdate3 = datetime.date(1985, 12, 1)
    if birthdate3 is not None:
        assert calculate_age(birthdate3) == 37, f"Expected 37, got {calculate_age(birthdate3)}"

    # Birthday earlier in the year
    birthdate4 = datetime.date(1995, 5, 10)
    if birthdate4 is not None:
        assert calculate_age(birthdate4) == 28, f"Expected 28, got {calculate_age(birthdate4)}"

    # Birthday on the same day (current date)
    birthdate5 = datetime.date(1973, 10, 26)
    if birthdate5 is not None:
        assert calculate_age(birthdate5) == 50, f"Expected 50, got {calculate_age(birthdate5)}"

    # Birthday day just after current day
    birthdate6 = datetime.date(1973, 10, 27)
    if birthdate6 is not None:
        assert calculate_age(birthdate6) == 49, f"Expected 49, got {calculate_age(birthdate6)}"

    # Test None input
    none_birthdate = None
    try:
        if none_birthdate is None:
            calculate_age(none_birthdate)
    except ValueError as e:
        assert str(e) == "Birthdate cannot be None."

    print("All test cases passed!")

test_age_calculation()

