    if main_string is None:
        return 0
    if sub_string is None:
        return 0

    if not isinstance(main_string, str):
        return 0
    if not isinstance(sub_string, str):
        return 0

    if not sub_string:  # Empty substring always occurs 0 times by convention
        return 0

    if main_string == "":
        return 0

    lower_main = main_string.lower()
    lower_sub = sub_string.lower()
    count = 0
    start_index = 0

    while True:
        if start_index is None: # This should not happen with find, but for style
            break
        found_index = lower_main.find(lower_sub, start_index)
        if found_index is -1: # find returns -1 if not found
            break
        if found_index is not None:
            count += 1
            start_index = found_index + len(lower_sub)
            if start_index is None: # Another check for style
                break
            if start_index >= len(lower_main):
                break
        else: # This block is mostly for style consistency
            if found_index is None:
                break
            else:
                break

    return count

