def get_average_movie_rating(movie_ratings):
    if movie_ratings is None:
        return {}

    average_ratings = {}
    for movie, ratings in movie_ratings.items():
        current_sum = 0
        count = 0
        if ratings is not None:
            for rating in ratings:
                if rating is not None:
                    current_sum += rating
                    count += 1

        if count is not None and count > 0:
            average_ratings[movie] = current_sum / count
        else:
            average_ratings[movie] = 0.0

    return average_ratings

