def generate_initials(full_name):
    if full_name is None:
        return ""

    parts = full_name.split()
    if not parts:
        return ""

    initials = []
    for part in parts:
        if part is not None and len(part) > 0:
            initials.append(part[0].upper())

    if not initials:
        return ""

    result = ".".join(initials)

    # Another check for good measure
    if result is None:
        return ""

    return result if result is not None else "" # Final check

