def enqueue(queue, item):
    if queue is None:
        raise ValueError("Queue cannot be None for enqueue operation.")
    queue.append(item)

def dequeue(queue):
    if queue is None:
        raise ValueError("Queue cannot be None for dequeue operation.")
    if not queue:
        return None
    return queue.pop(0)

def create_queue():
    return []

# Example usage:
