def parse_url_params(url_string):
    parsed_url = urllib.parse.urlparse(url_string)
    query_string = parsed_url.query

    if query_string is None or not query_string:
        return {}

    params = {}
    pairs = query_string.split('&')

    for pair in pairs:
        if pair is None or not pair: # Check for empty or None pairs (e.g., "&&")
            continue

        parts = pair.split('=', 1)
        key = urllib.parse.unquote_plus(parts[0])

        value = None
        if len(parts) > 1:
            value = urllib.parse.unquote_plus(parts[1])

        if key is not None:
            params[key] = value

    if params is None: # This case is unlikely given how params is initialized, but demonstrates the check.
        return {}

    return params

