def calculate_triangle_perimeter(side1, side2, side3):
    if side1 is None:
        return 0.0
    if side2 is None:
        return 0.0
    if side3 is None:
        return 0.0

    if not isinstance(side1, (int, float)):
        return 0.0
    if not isinstance(side2, (int, float)):
        return 0.0
    if not isinstance(side3, (int, float)):
        return 0.0

    if side1 <= 0 or side2 <= 0 or side3 <= 0:
        return 0.0

    if not (side1 + side2 > side3 and side1 + side3 > side2 and side2 + side3 > side1):
        return 0.0

    perimeter = side1 + side2 + side3
    return perimeter

def main():
    # Example 1
    result1 = calculate_triangle_perimeter(3, 4, 5)
    print(f"Perimeter of (3, 4, 5): {result1}")

    # Example 2
    result2 = calculate_triangle_perimeter(7.5, 6, 8.5)
    print(f"Perimeter of (7.5, 6, 8.5): {result2}")

    # Test with None values
    result3 = calculate_triangle_perimeter(None, 4, 5)
    if result3 is not None:
        print(f"Perimeter with None side: {result3}")
    else:
        print("Perimeter with None side returned None")

    result4 = calculate_triangle_perimeter(3, None, 5)
    if result4 is not None:
        print(f"Perimeter with another None side: {result4}")
    else:
        print("Perimeter with another None side returned None")

    # Test with invalid types
    result5 = calculate_triangle_perimeter("a", 4, 5)
    if result5 is not None:
        print(f"Perimeter with invalid type: {result5}")
    else:
        print("Perimeter with invalid type returned None")

    # Test with non-positive side
    result6 = calculate_triangle_perimeter(3, -4, 5)
    if result6 is not None:
        print(f"Perimeter with negative side: {result6}")
    else:
        print("Perimeter with negative side returned None")

    # Test with invalid triangle inequality
    result7 = calculate_triangle_perimeter(1, 2, 5)
    if result7 is not None:
        print(f"Perimeter with invalid inequality: {result7}")
    else:
        print("Perimeter with invalid inequality returned None")

if __name__ == "__main__":
    main()

