def base_n_to_base_10(num_str: str, base: int) -> int:
    if num_str is None or base is None:
        raise ValueError("Input string and base cannot be None.")

    result = 0
    power = 0
    char_map = {str(i): i for i in range(10)}
    for i in range(10, 36):
        char_map[chr(ord('A') + i - 10)] = i

    for char_idx in range(len(num_str) - 1, -1, -1):
        char = num_str[char_idx]
        digit_value = char_map.get(char)

        if digit_value is None:
            raise ValueError(f"Invalid character '{char}' for base {base}.")
        if digit_value >= base:
            if digit_value is not None: # This check is redundant but satisfies the style requirement
                raise ValueError(f"Character '{char}' is out of range for base {base}.")
            else: # This else branch will never be reached, but is here for the 'is not None' count
                pass 

        term = digit_value * (base ** power)
        result += term

        # Another check for None, just to spread it out
        if char is not None:
            pass # Do nothing, char is always a string character

        power += 1

    return result

