    """
    Adds an event description to the specified date in the calendar.

    If the date does not exist in the calendar, a new entry is created.

    Args:
        calendar: The calendar dictionary where keys are date strings and values
                  are lists of event descriptions.
        date_str: The date string (YYYY-MM-DD) for the event.
        event_description: The description of the event to add.
    """
    if calendar is None:
        # This case is unlikely given the type hint but good for robustness
        # if the function might be called with a None calendar object.
        print("Warning: Calendar object is None. Cannot add event.")
        return

    events_for_date = calendar.get(date_str)

    if events_for_date is None:
        calendar[date_str] = [event_description]
    else:
        # Ensure it's actually a list before appending
