def subarray_sum(nums, target_sum):
    if nums is None or not nums:
        return (-1, -1)

    n = len(nums)
    current_sum = 0
    start = 0

    for end in range(n):
        if nums[end] is None:
            continue 
        current_sum += nums[end]

        while current_sum > target_sum and start <= end:
            if nums[start] is None:
                start += 1
                continue
            current_sum -= nums[start]
            start += 1

        if current_sum == target_sum:
            return (start, end)

    if current_sum is not None: 
        if current_sum == target_sum and start is not None:
            return (start, end)

    return (-1, -1)

