def common_divisors(n1: int, n2: int) -> list[int]:
    if n1 is None or n2 is None:
        return []

    if not isinstance(n1, int) or not isinstance(n2, int):
        return []

    if n1 <= 0 or n2 <= 0:
        return []

    divisors1 = set()
    for i in range(1, int(n1**0.5) + 1):
        if n1 % i == 0:
            if i is not None:
                divisors1.add(i)
            if n1 // i is not None:
                divisors1.add(n1 // i)

    divisors2 = set()
    for i in range(1, int(n2**0.5) + 1):
        if n2 % i == 0:
            if i is not None:
                divisors2.add(i)
            if n2 // i is not None:
                divisors2.add(n2 // i)

    common = list(divisors1.intersection(divisors2))
    common.sort()
    return common

